Resource Blocks:
resource "aws_s3_bucket" "data" {
  bucket = "my-app-data-bucket"
  acl    = "private"

tags = {
    Name = "Data Bucket"
  }
}

Data Sources:
data "aws_ami" "ubuntu" {
  most_recent = true
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-focal-20.04-amd64-server-*"]
  }
}

Input Variables:
variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t3.micro"

  validation {
    condition     = contains(["t3.micro", "t3.small"], var.instance_type)
    error_message = "Instance type must be t3.micro or t3.small."
  }
}

Outputs:
output "instance_ip" {
  description = "Public IP of web instance"
  value       = aws_instance.web.public_ip
}

Locals:
locals {
  name_prefix = "${var.environment}-web"
  common_tags = {
    Environment = var.environment
    Project     = "MyApp"
  }
}

Remote State:
terraform {
  backend "s3" {
    bucket         = "my-terraform-state"
    key            = "prod/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
  }
}

State Locking:
// DynamoDB table referenced in S3 backend above
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
}

Root Module:
# root main.tf
module "networking" {
  source = "./modules/networking"
}

module "compute" {
  source = "./modules/compute"
}

Child Modules:
# modules/networking/main.tf
variable "vpc_cidr" {}
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
}
output "vpc_id" {
  value = aws_vpc.main.id
}

remote-exec:
provisioner "remote-exec" {
  inline = [
    "sudo apt update",
    "sudo apt install -y nginx",
    "sudo systemctl start nginx"
  ]
}

Best Practices:
resource "aws_instance" "web" {
  user_data = <<-EOF
    #!/bin/bash
    apt update && apt install -y nginx
  EOF
}

Environment Separation:
locals {
  env = terraform.workspace
  name = "${local.env}-app"
}

resource "aws_instance" "web" {
  instance_type = local.env == "production" ? "t3.large" : "t3.micro"
}

Import:
terraform import aws_instance.web i-0abcd1234efgh5678

# After import, write matching config:
resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t2.micro"
}

Sensitive Values:
variable "db_password" {
  type      = string
  sensitive = true
}

output "password" {
  value     = var.db_password
  sensitive = true
}

Sentinel:
import "tfplan"

main = rule {
  all tfplan.resources.aws_instance as _, instances {
    instances.applied.instance_type != "t2.micro"
  }
}
